func newImportIgnoreMatcher(ignoredFields []string) importIgnoreMatcher {
	var patterns [][]string
	var counterparts []woCounterpart
	seen := make(map[string]bool)

	addPattern := func(raw string) {
		trimmed := strings.TrimSpace(raw)
		trimmed = strings.TrimSuffix(trimmed, ".#")
		trimmed = strings.TrimSuffix(trimmed, ".%")
		trimmed = strings.TrimSuffix(trimmed, ".")
		if trimmed == "" || seen[trimmed] {
			return
		}
		seen[trimmed] = true
		tokens := strings.Split(trimmed, ".")
		patterns = append(patterns, tokens)

		// Add label/annotation computed companions for nested metadata blocks
		// (e.g. "metadata.0.labels" -> "metadata.0.terraform_labels", "metadata.0.effective_labels").
		last := tokens[len(tokens)-1]
		prefix := tokens[:len(tokens)-1]
		switch last {
		case "labels":
			addCompanion(prefix, "terraform_labels", seen, &patterns)
			addCompanion(prefix, "effective_labels", seen, &patterns)
		case "annotations":
			addCompanion(prefix, "effective_annotations", seen, &patterns)
		}

		if base, ok := strings.CutSuffix(last, "_wo_version"); ok && base != "" {
			baseTokens := append(slices.Clone(prefix), base)
			counterparts = append(counterparts, woCounterpart{
				basePattern:      baseTokens,
				woVersionPattern: tokens,
			})
		}
	}

	for _, f := range defaultImportIgnoredRootFields {
		addPattern(f)
	}
	for _, f := range ignoredFields {
		addPattern(f)
	}

	return importIgnoreMatcher{
		patterns:              patterns,
		woVersionCounterparts: counterparts,
	}
}

func addCompanion(prefix []string, leaf string, seen map[string]bool, patterns *[][]string) {
	full := append(slices.Clone(prefix), leaf)
	joined := strings.Join(full, ".")
	if !seen[joined] {
		seen[joined] = true
		*patterns = append(*patterns, full)
	}
}

// isIgnored reports whether segs matches or is nested beneath any ignored pattern,
// or is a Terraform write-only (*_wo) attribute.
