func (c *importNoReplaceAndOnlyIgnoredDiffsCheck) CheckPlan(_ context.Context, req plancheck.CheckPlanRequest, resp *plancheck.CheckPlanResponse) {
	if req.Plan == nil {
		resp.Error = fmt.Errorf("import plan check for %s: plan is nil", c.resourceAddress)
		return
	}

	var target *tfjson.ResourceChange
	for _, rc := range req.Plan.ResourceChanges {
		if rc != nil && rc.Address == c.resourceAddress {
			target = rc
			break
		}
	}
	if target == nil || target.Change == nil {
		resp.Error = fmt.Errorf("import plan check: resource %q not found in plan resource_changes", c.resourceAddress)
		return
	}

	actions := target.Change.Actions
	switch {
	case actions.NoOp() || actions.Read():
		return

	case actions.Replace():
		resp.Error = c.checkReplace(target)
		return

	case actions.Update():
		resp.Error = c.checkUpdate(target)
		return

	default:
		resp.Error = fmt.Errorf("importing resource %s: unexpected plan actions %v", c.resourceAddress, actions)
		return
	}
}

func (c *importNoReplaceAndOnlyIgnoredDiffsCheck) checkReplace(rc *tfjson.ResourceChange) error {
	change := rc.Change
	if len(change.ReplacePaths) == 0 {
		return fmt.Errorf("importing resource %s: unexpected replacement plan (%v) with empty replace_paths", c.resourceAddress, change.Actions)
	}

	var unignored []string
	hasExplainedIgnoredPath := false

	for _, rawPath := range change.ReplacePaths {
		segs, ok := parseReplacePath(rawPath)
		if !ok || len(segs) == 0 {
			unignored = append(unignored, fmt.Sprintf("%v", rawPath))
			continue
		}

		// In terraform-plugin-sdk/v2 (grpc_provider.go), whenever any attribute has
		// RequiresNew, the SDK unconditionally appends ["id"] to RequiresReplace.
		// Treat ["id"] as a companion only when at least one ignored attribute path
		// in ReplacePaths explains the replacement (unless "id" itself is ignored).
		if len(segs) == 1 && !segs[0].isIndex && segs[0].key == "id" {
			if c.matcher.isIgnored(segs) {
				hasExplainedIgnoredPath = true
			}
			continue
		}

		if c.matcher.isIgnored(segs) || c.matcher.isActiveWriteOnlyCounterpart(segs, change.After) {
			hasExplainedIgnoredPath = true
			continue
		}

		// SDKv2 hcl2shim truncates RequiresReplace paths at TypeSet boundaries
		// (e.g. ["grpc_services"] when "grpc_services.0.file_descriptor_set" is ForceNew).
		// Allow a container path only when it has an ignored descendant and all diffs
		// within that container subtree are on ignored attributes.
		if c.matcher.hasDescendantIgnore(segs) {
			beforeSub := lookupAtPath(change.Before, segs)
			afterSub := lookupAtPath(change.After, segs)
			unknownSub := lookupAtPath(change.AfterUnknown, segs)
			subDiffs := c.collectUnignoredDiffs(segs, beforeSub, afterSub, unknownSub, change.After)
			if len(subDiffs) == 0 && !reflect.DeepEqual(beforeSub, afterSub) {
				hasExplainedIgnoredPath = true
				continue
			}
		}

		unignored = append(unignored, formatPath(segs))
	}

	if len(unignored) > 0 {
		slices.Sort(unignored)
		return fmt.Errorf("importing resource %s: unexpected replacement plan (%v) caused by unignored replace_paths %v", c.resourceAddress, change.Actions, unignored)
	}
	if !hasExplainedIgnoredPath {
		return fmt.Errorf("importing resource %s: unexpected replacement plan (%v) with replace_paths %v not explained by ignored fields", c.resourceAddress, change.Actions, change.ReplacePaths)
	}
	return nil
}

func (c *importNoReplaceAndOnlyIgnoredDiffsCheck) checkUpdate(rc *tfjson.ResourceChange) error {
	change := rc.Change
	diffs := c.collectUnignoredDiffs(nil, change.Before, change.After, change.AfterUnknown, change.After)
	if len(diffs) > 0 {
		slices.Sort(diffs)
		return fmt.Errorf("importing resource %s: unexpected plan diff on non-ignored attribute(s):\n  %s", c.resourceAddress, strings.Join(diffs, "\n  "))
	}
	return nil
}

func (c *importNoReplaceAndOnlyIgnoredDiffsCheck) collectUnignoredDiffs(segs []pathSegment, beforeVal, afterVal, unknownVal, afterRoot any) []string {
	if len(segs) > 0 {
		if c.matcher.isIgnored(segs) || c.matcher.isActiveWriteOnlyCounterpart(segs, afterRoot) {
			return nil
		}
	}
	if b, ok := unknownVal.(bool); ok && b {
		return nil
	}
	if reflect.DeepEqual(beforeVal, afterVal) {
		return nil
	}
	if isEmptyContainerOrNil(beforeVal) && isEmptyContainerOrNil(afterVal) {
		return nil
	}

	beforeMap, bIsMap := beforeVal.(map[string]any)
	afterMap, aIsMap := afterVal.(map[string]any)
	if bIsMap && aIsMap {
		unknownMap, _ := unknownVal.(map[string]any)
		keys := unionKeys(beforeMap, afterMap)
		var diffs []string
		for _, k := range keys {
			var uChild any
			if unknownMap != nil {
				uChild = unknownMap[k]
			}
			childSegs := appendSegment(segs, pathSegment{key: k, isIndex: false})
			diffs = append(diffs, c.collectUnignoredDiffs(childSegs, beforeMap[k], afterMap[k], uChild, afterRoot)...)
		}
		return diffs
	}

	afterSlice, aIsSlice := afterVal.([]any)
	beforeSlice, bIsSlice := beforeVal.([]any)
	if aIsSlice && (bIsSlice || beforeVal == nil) {
		unknownSlice, _ := unknownVal.([]any)
		if len(beforeSlice) == len(afterSlice) {
			var diffs []string
			for i := range afterSlice {
				var uElem any
				if i < len(unknownSlice) {
					uElem = unknownSlice[i]
				}
				childSegs := appendSegment(segs, pathSegment{key: strconv.Itoa(i), isIndex: true})
				diffs = append(diffs, c.collectUnignoredDiffs(childSegs, beforeSlice[i], afterSlice[i], uElem, afterRoot)...)
			}
			// Handle TypeSet reordering when an ignored nested field changed one element's sort key.
			if len(diffs) > 0 && len(afterSlice) > 1 && c.matcher.hasDescendantIgnore(segs) {
				if c.multisetEqualAfterStrip(segs, beforeSlice, afterSlice, unknownSlice, afterRoot) {
					return nil
				}
			}
			return diffs
		}

		// When a nested block only had write-only / ignore_read fields configured, Read on
		// fresh import may return an empty slice [] while After plans the 1-element block.
		if len(beforeSlice) == 0 && len(afterSlice) > 0 && c.isSliceExplainedByIgnoredFields(segs, afterSlice, unknownSlice, afterRoot) {
			return nil
		}

		return []string{fmt.Sprintf("%s: slice length before=%d, after=%d (before=%#v, after=%#v)", formatPath(segs), len(beforeSlice), len(afterSlice), beforeVal, afterVal)}
	}

	return []string{fmt.Sprintf("%s: before=%#v, after=%#v", formatPath(segs), beforeVal, afterVal)}
}

func (c *importNoReplaceAndOnlyIgnoredDiffsCheck) isSliceExplainedByIgnoredFields(segs []pathSegment, afterSlice, unknownSlice []any, afterRoot any) bool {
	for i, elem := range afterSlice {
		elemMap, ok := elem.(map[string]any)
		if !ok {
			return false
		}
		var uElem any
		if i < len(unknownSlice) {
			uElem = unknownSlice[i]
		}
		elemSegs := appendSegment(segs, pathSegment{key: strconv.Itoa(i), isIndex: true})
		hasIgnored, allAccounted := c.objectOnlyHasIgnoredOrZeroFields(elemSegs, elemMap, uElem, afterRoot)
		if !hasIgnored || !allAccounted {
			return false
		}
	}
	return true
}

func (c *importNoReplaceAndOnlyIgnoredDiffsCheck) objectOnlyHasIgnoredOrZeroFields(segs []pathSegment, m map[string]any, unknownVal, afterRoot any) (hasIgnored bool, allAccounted bool) {
	unknownMap, _ := unknownVal.(map[string]any)
	for k, v := range m {
		childSegs := appendSegment(segs, pathSegment{key: k, isIndex: false})
		if c.matcher.isIgnored(childSegs) || c.matcher.isActiveWriteOnlyCounterpart(childSegs, afterRoot) {
			hasIgnored = true
			continue
		}
		var uChild any
		if unknownMap != nil {
			uChild = unknownMap[k]
		}
		if b, ok := uChild.(bool); ok && b {
			continue
		}
		if isNullOrZeroValue(v) {
			continue
		}
		if subMap, ok := v.(map[string]any); ok {
			subHasIgnored, subOk := c.objectOnlyHasIgnoredOrZeroFields(childSegs, subMap, uChild, afterRoot)
			if !subOk {
				return false, false
			}
			if subHasIgnored {
				hasIgnored = true
			}
			continue
		}
		if subSlice, ok := v.([]any); ok {
			subUnknownSlice, _ := uChild.([]any)
			if c.isSliceExplainedByIgnoredFields(childSegs, subSlice, subUnknownSlice, afterRoot) {
				hasIgnored = true
				continue
			}
		}
		return false, false
	}
	return hasIgnored, true
}

func (c *importNoReplaceAndOnlyIgnoredDiffsCheck) multisetEqualAfterStrip(segs []pathSegment, beforeSlice, afterSlice, unknownSlice []any, afterRoot any) bool {
	if len(beforeSlice) != len(afterSlice) {
		return false
	}
	used := make([]bool, len(beforeSlice))
	for j, aElem := range afterSlice {
		var uElem any
		if j < len(unknownSlice) {
			uElem = unknownSlice[j]
		}
		elemSegs := appendSegment(segs, pathSegment{key: strconv.Itoa(j), isIndex: true})
		matched := false
		for i, bElem := range beforeSlice {
			if used[i] {
				continue
			}
			if len(c.collectUnignoredDiffs(elemSegs, bElem, aElem, uElem, afterRoot)) == 0 {
				used[i] = true
				matched = true
				break
			}
		}
		if !matched {
			return false
		}
	}
	return true
}

func parseReplacePath(raw any) ([]pathSegment, bool) {
	steps, ok := raw.([]any)
	if !ok {
		return nil, false
	}
	segs := make([]pathSegment, 0, len(steps))
	for _, step := range steps {
		switch v := step.(type) {
		case string:
			segs = append(segs, pathSegment{key: v, isIndex: false})
		case int:
			segs = append(segs, pathSegment{key: strconv.Itoa(v), isIndex: true})
		case int64:
			segs = append(segs, pathSegment{key: strconv.FormatInt(v, 10), isIndex: true})
		case float64:
			segs = append(segs, pathSegment{key: strconv.FormatInt(int64(v), 10), isIndex: true})
		case json.Number:
			segs = append(segs, pathSegment{key: v.String(), isIndex: true})
		default:
			return nil, false
		}
	}
	return segs, true
}

func lookupAtPath(root any, segs []pathSegment) any {
	curr := root
	for _, seg := range segs {
		if curr == nil {
			return nil
		}
		if seg.isIndex {
			sl, ok := curr.([]any)
			if !ok {
				return nil
			}
			idx, err := strconv.Atoi(seg.key)
			if err != nil || idx < 0 || idx >= len(sl) {
				return nil
			}
			curr = sl[idx]
		} else {
			m, ok := curr.(map[string]any)
			if !ok {
				return nil
			}
			curr = m[seg.key]
		}
	}
	return curr
}

func isEmptyContainerOrNil(v any) bool {
	if v == nil {
		return true
	}
	switch tv := v.(type) {
	case []any:
		return len(tv) == 0
	case map[string]any:
		return len(tv) == 0
	default:
		return false
	}
}

func isNullOrZeroString(v any) bool {
	if v == nil {
		return true
	}
	s, ok := v.(string)
	return ok && s == ""
}

func isNullOrZeroValue(v any) bool {
	if isEmptyContainerOrNil(v) {
		return true
	}
	s, ok := v.(string)
	return ok && s == ""
}

func unionKeys(a, b map[string]any) []string {
	seen := make(map[string]struct{}, len(a)+len(b))
	for k := range a {
		seen[k] = struct{}{}
	}
	for k := range b {
		seen[k] = struct{}{}
	}
	keys := make([]string, 0, len(seen))
	for k := range seen {
		keys = append(keys, k)
	}
	slices.Sort(keys)
	return keys
}

func appendSegment(segs []pathSegment, seg pathSegment) []pathSegment {
	out := make([]pathSegment, len(segs)+1)
	copy(out, segs)
	out[len(segs)] = seg
	return out
}

func formatPath(segs []pathSegment) string {
	if len(segs) == 0 {
		return "<root>"
	}
	parts := make([]string, len(segs))
	for i, s := range segs {
		parts[i] = s.key
	}
	return strings.Join(parts, ".")
}
